import json
s=json.load(open('spec/fossa-openapi.json'))
paths=s['paths']
print("=== Dependencies-tagged paths (the 'packages' surface) ===")
for p,item in sorted(paths.items()):
    for m,op in item.items():
        if m in ('get','put','post','patch','delete') and 'Dependencies' in (op.get('tags') or []):
            print(f"  {m.upper():6} {p}")
print()
print("=== quality org-settings endpoint ===")
op=paths['/organizations/{id}/settings/projects/issues/quality']
for m,o in op.items():
    if m in ('get','put','patch'):
        print(f"  {m.upper()} — {o.get('summary','')}")
        rb=o.get('requestBody')
        if rb:
            sch=rb['content']['application/json']['schema']
            print("   body props:", list(sch.get('properties',{}).keys()))
print()
print("=== where qualityPolicyId is settable ===")
for p,item in sorted(paths.items()):
    for m,o in item.items():
        if m not in ('get','put','post','patch','delete'): continue
        rb=o.get('requestBody')
        if not rb: continue
        try: props=rb['content']['application/json']['schema'].get('properties',{})
        except Exception: continue
        if 'qualityPolicyId' in props:
            print(f"  {m.upper():6} {p}  -> {props['qualityPolicyId']}")
